from pathlib import Path
import json
rows=json.loads(Path('tmp/native-npc-branch-service.json').read_text())
def state(s):
 return '{%s,%s,{%s},%s}'%(','.join(str(s[k]) for k in ['mode','event','progress','context','npcContext','npcState','followup','next','mapInit','pointer']),','.join(str(s[k]) for k in ['offset','more','style']),','.join(map(str,s['rect'])),','.join(str(s[k]) for k in ['money','npc32','guardIndex','guardWordIndex','guardA','guardB']))
lines=['/* Original-only fixtures; generated by generate_npc_condition_dialogue_fixture.py. */',
 'typedef struct {uint32_t mode,event,progress,context,npc_context,npc_state,followup,next,map_init,pointer;uint16_t offset,more,style,rect[4];uint32_t money;uint16_t npc32,guard_index,guard_word_index,guard_a,guard_b;} NpcTextState;',
 'typedef struct {const char *name;unsigned npc,count,patch,key,closes,shortcut,ignored;NpcTextState before,pages[25],patch_before,after;unsigned commits;} NpcTextCase;',
 'static const NpcTextCase npc_text_cases[]={']
for r in rows:
 p=r['patched'][0] if r['patched'] else None
 lines.append('{"%s",%d,%d,%d,%d,%d,%d,%d,%s,{%s},%s,%s,%d},'%(r['name'],r['npc'],len(r['pages']),bool(p),r.get('key',0x20),r.get('close',False),r.get('shortcut',False),r.get('ignored',False),state(r['before']),','.join(state(s) for s in r['pages']),state(p['before']) if p else '{0}',state(r['after']),len(p['commits']) if p else 0))
lines+=['};']
Path('npe-sdl/tests/npc_condition_dialogue_native.h').write_text('\n'.join(lines)+'\n')
